"use client";
import {ArtemisScope} from "./artemis-scope";
import View8 from "./components/not-found-pages/variants/09-wayfinder";
const views={"wayfinder":View8};
export interface ArtemisNotFoundPagesProps{className?:string;variant?:"wayfinder";}
export function ArtemisNotFoundPages({className,variant="wayfinder"}:ArtemisNotFoundPagesProps){const View=views[variant];return <ArtemisScope className={["art:min-h-dvh art:[&>section]:min-h-dvh",className].filter(Boolean).join(" ")}><View/></ArtemisScope>;}

"use client";
// @zeus-internal
import { useEffect, useState } from "react";
import { motion, useReducedMotion } from "motion/react";
import { ARTEMIS_EASE_OUT, ARTEMIS_SPRING_PANEL, ARTEMIS_SPRING_PRESS } from "../../../lib/ease";
export default function NotFoundPagesWayfinder() {
    const reduce = useReducedMotion();
    const [copyShown, setCopyShown] = useState(false);
    const [routeShown, setRouteShown] = useState(false);
    const [markersShown, setMarkersShown] = useState(false);
    useEffect(() => {
        const copy = setTimeout(() => setCopyShown(true), 80);
        const route = setTimeout(() => setRouteShown(true), 220);
        const markers = setTimeout(() => setMarkersShown(true), 420);
        return () => { clearTimeout(copy); clearTimeout(route); clearTimeout(markers); };
    }, []);
    const press = { whileHover: reduce ? undefined : { scale: 1.01 }, whileTap: reduce ? undefined : { scale: 0.99 }, transition: ARTEMIS_SPRING_PRESS };
    return (<>
      <section className="art:relative art:isolate art:flex art:min-h-[680px] art:w-full art:flex-col art:overflow-hidden art:bg-background art:text-foreground">
        <header className="art:relative art:z-20 art:flex art:min-h-20 art:items-center art:justify-between art:px-5 art:@min-[640px]/artemis:px-8">
