                <circle cx="12" cy="12" r="10"/>
                <path d="m16.24 7.76-1.804 5.411a2 2 0 0 1-1.265 1.265L7.76 16.24l1.804-5.411a2 2 0 0 1 1.265-1.265z"/>
              </svg>
            </span>
            {"Workspace"}
          </a>
          <span className="art:font-mono art:text-xs art:opacity-45 art:uppercase art:tracking-[0.18em]">
            {"404"}
          </span>
        </header>
        <div className="art:relative art:z-10 art:flex art:flex-1 art:flex-col art:justify-between art:gap-10 art:px-5 art:pb-8 art:@min-[640px]/artemis:px-8 art:@min-[1024px]/artemis:flex-row art:@min-[1024px]/artemis:items-end art:@min-[1024px]/artemis:gap-16">
          <motion.div initial={{ opacity: 0, y: 16 }} animate={{ opacity: copyShown || reduce ? 1 : 0, y: copyShown || reduce ? 0 : 16 }} transition={reduce ? { duration: 0 } : ARTEMIS_SPRING_PANEL} className="art:max-w-xl art:pb-6 art:@min-[1024px]/artemis:pb-12">
            <div className="art:inline-flex art:items-center art:gap-2 art:rounded-full art:bg-muted art:px-3 art:py-1.5 art:font-medium art:text-foreground art:text-xs">
              <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-map-pin art:size-3.5" aria-hidden="true">
                <path d="M20 10c0 4.993-5.539 10.193-7.399 11.799a1 1 0 0 1-1.202 0C9.539 20.193 4 14.993 4 10a8 8 0 0 1 16 0"/>
                <circle cx="12" cy="10" r="3"/>
              </svg>
              {"404 \u00B7 off the map"}
            </div>
            <h1 className="art:mt-6 art:max-w-lg art:text-balance art:font-sans art:leading-tight art:tracking-[-0.045em] art:text-4xl art:@min-[768px]/artemis:text-5xl art:font-medium">
              {"Wrong turn."}
            </h1>
            <motion.a {...press} className="art:inline-flex art:items-center art:justify-center art:font-medium art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:gap-2 art:px-6 art:text-base art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:mt-7 art:bg-primary art:text-primary-foreground art:hover:bg-primary/85 art:h-9 art:rounded-full" href="/" tabIndex={0}>
              <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-arrow-left art:size-4" aria-hidden="true">
                <path d="m12 19-7-7 7-7"/>
                <path d="M19 12H5"/>
              </svg>
              {"Go home"}
            </motion.a>
          </motion.div>
          <div aria-hidden="true" className="art:relative art:aspect-[1.08] art:w-full art:max-w-[570px] art:shrink-0 art:overflow-hidden art:rounded-3xl art:bg-muted">
            <svg viewBox="0 0 570 530" className="art:absolute art:inset-0 art:size-full" role="presentation">
