              <path d="M120 500C128 411 67 350 121 280C170 216 257 246 286 183C320 110 278 66 311 -30" fill="none" stroke="currentColor" strokeOpacity="0.06" strokeWidth="22"/>
              <motion.path initial={{ opacity: 0, pathLength: reduce ? 1 : 0 }} animate={{ opacity: routeShown || reduce ? 1 : 0, pathLength: routeShown || reduce ? 1 : 0 }} transition={{ duration: reduce ? 0 : 0.9, ease: ARTEMIS_EASE_OUT }} d="M62 420C103 375 91 303 165 285C239 267 274 331 339 281C400 234 367 168 485 112" fill="none" stroke="var(--artemis-foreground)" strokeWidth="5" strokeLinecap="round"/>
