              <span className="art:block art:size-3 art:rounded-full art:border-[3px] art:border-background art:bg-primary art:ring-4 art:ring-primary/15"/>
              <span className="art:mt-2 art:block art:whitespace-nowrap art:rounded-full art:bg-background/80 art:px-2.5 art:py-1 art:font-medium art:text-foreground art:text-xs art:backdrop-blur-sm">
                {"Start"}
              </span>
            </motion.div>
            <motion.div initial={{ opacity: 0, scale: 0.7 }} animate={{ opacity: markersShown || reduce ? 1 : 0, scale: markersShown || reduce ? 1 : 0.7 }} transition={reduce ? { duration: 0 } : { ...ARTEMIS_SPRING_PANEL, delay: 1 * 0.08 }} className="art:absolute art:-translate-x-1/2 art:-translate-y-1/2" style={{ left: "48%", top: "51%" }}>
              <span className="art:block art:size-3 art:rounded-full art:border-[3px] art:border-background art:bg-primary art:ring-4 art:ring-primary/15"/>
              <span className="art:mt-2 art:block art:whitespace-nowrap art:rounded-full art:bg-background/80 art:px-2.5 art:py-1 art:font-medium art:text-foreground art:text-xs art:backdrop-blur-sm">
                {"Here"}
              </span>
            </motion.div>
            <motion.div initial={{ opacity: 0, scale: 0.8, rotate: -8 }} animate={{ opacity: markersShown || reduce ? 1 : 0, scale: markersShown || reduce ? 1 : 0.8, rotate: markersShown || reduce ? 0 : -8 }} transition={reduce ? { duration: 0 } : ARTEMIS_SPRING_PANEL} className="art:absolute art:right-[10%] art:top-[14%]">
              <span className="art:grid art:size-14 art:place-items-center art:rounded-full art:bg-primary art:text-primary-foreground">
                <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-map-pin art:size-6" aria-hidden="true">
                  <path d="M20 10c0 4.993-5.539 10.193-7.399 11.799a1 1 0 0 1-1.202 0C9.539 20.193 4 14.993 4 10a8 8 0 0 1 16 0"/>
                  <circle cx="12" cy="10" r="3"/>
                </svg>
              </span>
              <span className="art:mt-2 art:block art:rounded-full art:bg-primary art:px-3 art:py-1.5 art:text-center art:font-medium art:text-xs art:text-primary-foreground">
                {"404"}
              </span>
            </motion.div>
          </div>
        </div>
      </section>
    </>);
}
